CREATE USER IF NOT EXISTS "SA" PASSWORD '' ADMIN;             
CREATE CACHED TABLE "PUBLIC"."AGENT_EXECUTIONS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 1288) NOT NULL,
    "AGENT_ID" CHARACTER VARYING(40),
    "ATTEMPT" INTEGER NOT NULL,
    "DEGRADED" BOOLEAN NOT NULL,
    "DURATION_MS" BIGINT NOT NULL,
    "ERROR_MESSAGE" CHARACTER VARYING,
    "FAILURE_KIND" ENUM('PERMANENT', 'POLICY', 'TRANSIENT', 'VALIDATION'),
    "PROVIDER" CHARACTER VARYING(60),
    "STARTED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "STATUS" ENUM('FAILED_PERMANENT', 'FAILED_TRANSIENT', 'FALLBACK_SUCCESS', 'SUCCESS'),
    "TASK_KEY" CHARACTER VARYING(64),
    "TASK_REVISION" INTEGER NOT NULL,
    "WORKFLOW_ID" CHARACTER VARYING(255)
);   
